mirrorNewWebsitePathParams = func(isHttps /*bool*/, url /*string*/, req /*[]byte*/, rsp /*[]byte*/, body /*[]byte*/) {
    freq, err = fuzz.HTTPRequest(req, fuzz.https(isHttps))
    if err != nil {
        yakit.Error("解析HTTP请求失败: %v", err)
        return
    }

    host, port, _ = str.ParseStringToHostPort(url)
    addr = str.HostPort(host, port)

    // 获取所有参数进行去重标识
    params = freq.GetCommonParams()
    getpa = string(params)
    paths222 = ""

    // 去重机制
    if poc.GetHTTPRequestPath(req).Split("/")[-1] == "" {
        paths222 = poc.GetHTTPRequestPath(req)
        paths222 += addr
        paths222 += getpa
        paths222 = codec.Md5(paths222)
    } else {
        paths222 = poc.GetHTTPRequestPath(req)
        paths222 += addr
        paths222 += getpa
        paths222 = codec.Md5(paths222)
    }

    if db.GetProjectKey(paths222) == "fuzz-cors" {
        println("重复扫描，已跳过")
        return
    } else {
        db.SetProjectKey(paths222, "fuzz-cors")
    }

    //yakit.Info("测试目标：" + url)

    // CORS测试的Origin域名列表
    testOrigins = [
        "http://www.baidu.com",
    ]

    // 测试每个Origin
    for i = 0; i < len(testOrigins); i++ {
        testOrigin = testOrigins[i]
        //yakit.Info("测试Origin[%d]: %s", i+1, testOrigin)

        // 添加Origin头进行测试
        testResp, err = freq.FuzzHTTPHeader("Origin", testOrigin).ExecFirst()
        if err != nil {
            //yakit.Error("Origin %s 测试请求失败: %v", testOrigin, err)
            continue
        }

        // 使用poc.Split解析响应，只接收2个返回值
        respHeaders, respBody = poc.Split(testResp.ResponseRaw)
        allowOrigin = ""
        allowCredentials = ""

        // 将响应头转换为字符串进行分析
        respHeadersStr = string(respHeaders)

        // 使用字符串查找方式来获取CORS相关头
        // 按行分割响应头
        headerLines = str.Split(respHeadersStr, "\n")

        for _, line = range headerLines {
            line = str.TrimSpace(line)
            lineLower = str.ToLower(line)

            // 查找 Access-Control-Allow-Origin
            if str.HasPrefix(lineLower, "access-control-allow-origin:") {
                parts = str.Split(line, ":")
                if len(parts) >= 2 {
                    allowOrigin = str.TrimSpace(str.Join(parts[1:], ":"))
                }
            }

            // 查找 Access-Control-Allow-Credentials
            if str.HasPrefix(lineLower, "access-control-allow-credentials:") {
                parts = str.Split(line, ":")
                if len(parts) >= 2 {
                    allowCredentials = str.TrimSpace(str.Join(parts[1:], ":"))
                }
            }
        }

        //yakit.Info("Origin: %s -> Allow-Origin: %s, Allow-Credentials: %s", testOrigin, allowOrigin, allowCredentials)

        // 检查是否存在CORS漏洞
        // 条件1：Access-Control-Allow-Origin 回显了我们发送的Origin
        // 条件2：Access-Control-Allow-Credentials 为 true
        if allowOrigin != "" && str.ToLower(allowCredentials) == "true" {
            // 检查是否为危险的Origin回显
            if allowOrigin == testOrigin || allowOrigin == "*" {
                yakit.Error("发现CORS漏洞！Origin: %s", testOrigin)

                // 创建风险记录
                risk.NewRisk(url, 
                    risk.title(sprintf("【高危】目标 `%s` 存在CORS跨域资源共享漏洞", url)),
                    risk.request(testResp.RequestRaw),
                    risk.response(testResp.ResponseRaw),
                    risk.severity("high"),
                    risk.payload(sprintf("Origin: %s", testOrigin)),
                    risk.description(sprintf(
                        "【确认漏洞】检测到危险的CORS配置\n\n" +
                        "攻击详情：\n" +
                        "• 目标URL: %s\n" +
                        "• 测试Origin: %s\n" +
                        "• 响应Access-Control-Allow-Origin: %s\n" +
                        "• 响应Access-Control-Allow-Credentials: %s\n\n" +
                        "漏洞原理：\n" +
                        "服务器配置了不安全的CORS策略，允许任意域名或恶意域名进行跨域请求，" +
                        "并且允许携带凭据(Credentials)。这使得攻击者可以通过恶意网站" +
                        "发起跨域请求来窃取用户的敏感信息。\n\n" +
                        "风险评估：攻击者可以构造恶意页面，诱导用户访问后自动发起跨域请求，" +
                        "窃取用户在目标网站的敏感数据，如个人信息、账户余额等。",
                        url, testOrigin, allowOrigin, allowCredentials)),
                    risk.solution("【修复建议】\n1. 严格配置Access-Control-Allow-Origin，避免使用通配符*\n2. 建立Origin白名单，仅允许可信域名跨域访问\n3. 谨慎设置Access-Control-Allow-Credentials为true\n4. 定期审查CORS配置策略\n5. 实施CSP(Content Security Policy)作为额外防护"),
                )

                // 发现漏洞后可以继续测试其他Origin，了解漏洞影响范围
            }
        }

        // 每个Origin测试间隔1秒，避免请求过于频繁
        time.Sleep(1)
    }

    println("CORS漏洞检测完成")
}
